(function(root){let pending;root.BrandMedia={logoData:'data:image/png;base64,',portraitURL:'assets/edson-personagem-transparente.png',loadPortrait(){if(!pending)pending=fetch('assets/edson-personagem-transparente.png').then(r=>{if(!r.ok)throw Error('Não foi possível carregar o personagem. Tente novamente.');return r.arrayBuffer()}).then(b=>new Uint8Array(b)).catch(e=>{pending=null;throw e});return pending}}})(typeof window!=='undefined'?window:globalThis);

;(function(root){root.BrandMedia.getPortrait=async function(s){if(!s.reportPortrait)return {data:await this.loadPortrait(),type:'png',width:1122,height:1402};return {data:Uint8Array.from(atob(s.reportPortrait.split(',')[1]),c=>c.charCodeAt(0)),type:s.reportPortrait.startsWith('data:image/png')?'png':'jpg',width:s.portraitWidth,height:s.portraitHeight}};root.BrandMedia.fitPortrait=function(w,h,mw,mh){const scale=Math.min(mw/w,mh/h);return {width:w*scale,height:h*scale}}})(typeof window!=='undefined'?window:globalThis);
